    container discountLineListContainter, salesQuoteLineContainer, adjustmentLineListContainer, basePriceLineListContainter;
    GUPSalesBasePriceLineMap basePriceLineMap;
    RetailSalesQuotesDiscountLineMap discountLine;
    RetailSalesPriceAdjustmentLineMap adjustmentLine;

    ListEnumerator basePriceListEn = basePriceLineList.getEnumerator();
    ListEnumerator adjustmentEn = adjustmentLineList.getEnumerator();
    ListEnumerator discountEn = discountLineList.getEnumerator();

    salesQuoteLineContainer = buf2Con(retailSalesQuotationLine);

    while (basePriceListEn.moveNext())
    {
        basePriceLineMap = basePriceListEn.current();

        basePriceLineListContainter += [buf2Con(basePriceLineMap)];
    }

    while (adjustmentEn.moveNext())
    {
        adjustmentLine = adjustmentEn.current();

        adjustmentLineListContainer += [buf2Con(adjustmentLine)];
    }

    while (discountEn.moveNext())
    {
        discountLine = discountEn.current();

        discountLineListContainter += [buf2Con(discountLine)];
    }

    return [#CurrentVersion,#CurrentList2];
}

public boolean unpack(container _packedClass)
{
