    basePriceLineCount = conLen(basePriceLineListContainter);
    adjustmentLineCount = conLen(adjustmentLineListContainer);
    discountLineCount   = conLen(discountLineListContainter);

    basePriceLineList = new List(Types::Record);
    for (i = 1; i <= basePriceLineCount; i++)
    {
        basePriceLineContainter = conPeek(basePriceLineListContainter, i);
        basePriceLineMap = con2Buf(basePriceLineContainter);

        basePriceLineList.addEnd(basePriceLineMap);
